          locationId,
          alertType: alert.type,
          severity: alert.severity,
          score: analysisResult.score,
          reasonCode: alert.reasonCode,
          message: alert.message,
          metadata: alert.metadata ? JSON.stringify(alert.metadata) : null,
          acknowledged: false
        });
      }

      res.json(analysisResult);
