      switch(type) {
        case 'visibilidad': return d.visibilidad;
        case 'reseñas': return d.reseñas * 20; // Escalar para visualización
        case 'contenido': return d.contenido;
        case 'engagement': return d.engagement / 20; // Escalar para visualización
