      "expectedImpact": "impacto esperado"
    }
  ],
  "contentIdeas": ["idea1", "idea2", "idea3"],
  "trendingTopics": ["tendencia1", "tendencia2", "tendencia3"]
}
    `;

    try {
      const response = await openai.chat.completions.create({
