import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import type { ReviewSource, Location } from "@shared/schema";
import { 
  Plus, 
  Star, 
  Globe, 
  Facebook, 
  MapPin,
  Settings,
  Trash2,
  Calendar,
  BarChart3,
  ExternalLink
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";


export default function ReviewSourcesManager() {
  const { toast } = useToast();
  const [selectedLocation, setSelectedLocation] = useState<string>("");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingSource, setEditingSource] = useState<ReviewSource | null>(null);
  const [formData, setFormData] = useState({
    sourceName: '',
    sourceUrl: '',
    syncFrequency: 24,
    isActive: true
  });

  // Get locations
  const { data: locations = [] } = useQuery<Location[]>({
    queryKey: ['/api/businesses/locations'],
  });

  // Get review sources for selected location
  const { data: reviewSources = [], isLoading, refetch } = useQuery<ReviewSource[]>({
    queryKey: ['/api/locations', selectedLocation, 'review-sources'],
    enabled: !!selectedLocation,
  });

  // Create review source mutation
  const createSource = useMutation({
    mutationFn: async (data: any) => {
      const response = await apiRequest(`/api/locations/${selectedLocation}/review-sources`, {
        method: 'POST',
        data: data
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Fuente Agregada",
        description: "La fuente de reseñas se agregó correctamente.",
      });
      setIsDialogOpen(false);
      resetForm();
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo agregar la fuente de reseñas.",
        variant: "destructive",
      });
    },
  });

  // Update review source mutation
  const updateSource = useMutation({
    mutationFn: async ({ sourceId, data }: { sourceId: string; data: any }) => {
      const response = await apiRequest(`/api/review-sources/${sourceId}`, {
        method: 'PUT',
        data: data
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Fuente Actualizada",
        description: "La fuente de reseñas se actualizó correctamente.",
      });
      setIsDialogOpen(false);
      setEditingSource(null);
      resetForm();
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo actualizar la fuente de reseñas.",
        variant: "destructive",
      });
    },
  });

  // Delete review source mutation
  const deleteSource = useMutation({
    mutationFn: async (sourceId: string) => {
      await apiRequest(`/api/review-sources/${sourceId}`, {
        method: 'DELETE'
      });
    },
    onSuccess: () => {
      toast({
        title: "Fuente Eliminada",
        description: "La fuente de reseñas se eliminó correctamente.",
      });
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo eliminar la fuente de reseñas.",
        variant: "destructive",
      });
    },
  });

  const resetForm = () => {
    setFormData({
      sourceName: '',
      sourceUrl: '',
      syncFrequency: 24,
      isActive: true
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingSource) {
      updateSource.mutate({ sourceId: editingSource.id, data: formData });
    } else {
      createSource.mutate(formData);
    }
  };

  const handleEdit = (source: ReviewSource) => {
    setEditingSource(source);
    setFormData({
      sourceName: source.sourceName,
      sourceUrl: source.sourceUrl || '',
      syncFrequency: source.syncFrequency || 24,
      isActive: source.isActive
    });
    setIsDialogOpen(true);
  };

  const handleDelete = (sourceId: string) => {
    if (confirm('¿Estás seguro de que quieres eliminar esta fuente de reseñas?')) {
      deleteSource.mutate(sourceId);
    }
  };

  const getSourceIcon = (sourceName: string) => {
    switch (sourceName.toLowerCase()) {
      case 'google':
        return <Globe className="h-5 w-5 text-blue-600" />;
      case 'facebook':
        return <Facebook className="h-5 w-5 text-blue-800" />;
      case 'tripadvisor':
        return <MapPin className="h-5 w-5 text-green-600" />;
      case 'yelp':
        return <Star className="h-5 w-5 text-red-600" />;
      default:
        return <Globe className="h-5 w-5 text-gray-600" />;
    }
  };

  const formatLastSync = (lastSyncAt: Date | string | null) => {
    if (!lastSyncAt) return 'Nunca';
    const date = lastSyncAt instanceof Date ? lastSyncAt : new Date(lastSyncAt);
    return date.toLocaleDateString('es-MX', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-6" data-testid="review-sources-manager">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight" data-testid="title-review-sources">Fuentes de Reseñas</h1>
          <p className="text-muted-foreground">
            Configura las plataformas desde donde obtener reseñas
          </p>
        </div>
      </div>

      {/* Location Selector */}
      <Card data-testid="location-selector">
        <CardHeader>
          <CardTitle>Seleccionar Ubicación</CardTitle>
        </CardHeader>
        <CardContent>
          <Select value={selectedLocation} onValueChange={setSelectedLocation}>
            <SelectTrigger data-testid="select-location">
              <SelectValue placeholder="Selecciona una ubicación" />
            </SelectTrigger>
            <SelectContent>
              {locations.map((location) => (
                <SelectItem key={location.id} value={location.id}>
                  {location.name} - {location.city}, {location.state}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {selectedLocation && (
        <>
          {/* Add Source Button */}
          <div className="flex justify-end">
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
              <DialogTrigger asChild>
                <Button onClick={() => { setEditingSource(null); resetForm(); }} data-testid="button-add-source">
                  <Plus className="h-4 w-4 mr-2" />
                  Agregar Fuente
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>
                    {editingSource ? 'Editar' : 'Agregar'} Fuente de Reseñas
                  </DialogTitle>
                  <DialogDescription>
                    Configura una nueva plataforma para obtener reseñas de tu negocio.
                  </DialogDescription>
                </DialogHeader>
                <form onSubmit={handleSubmit} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="sourceName">Plataforma</Label>
                    <Select 
                      value={formData.sourceName} 
                      onValueChange={(value) => setFormData({ ...formData, sourceName: value })}
                    >
                      <SelectTrigger data-testid="select-source-name">
                        <SelectValue placeholder="Selecciona una plataforma" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="google">Google My Business</SelectItem>
                        <SelectItem value="facebook">Facebook</SelectItem>
                        <SelectItem value="tripadvisor">TripAdvisor</SelectItem>
                        <SelectItem value="yelp">Yelp</SelectItem>
                        <SelectItem value="custom">Personalizada</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="sourceUrl">URL (Opcional)</Label>
                    <Input
                      id="sourceUrl"
                      type="url"
                      value={formData.sourceUrl}
                      onChange={(e) => setFormData({ ...formData, sourceUrl: e.target.value })}
                      placeholder="https://ejemplo.com/reviews"
                      data-testid="input-source-url"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="syncFrequency">Frecuencia de Sincronización (horas)</Label>
                    <Input
                      id="syncFrequency"
                      type="number"
                      min="1"
                      max="168"
                      value={formData.syncFrequency}
                      onChange={(e) => setFormData({ ...formData, syncFrequency: parseInt(e.target.value) })}
                      data-testid="input-sync-frequency"
                    />
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="isActive"
                      checked={formData.isActive}
                      onCheckedChange={(checked) => setFormData({ ...formData, isActive: checked })}
                      data-testid="switch-is-active"
                    />
                    <Label htmlFor="isActive">Fuente activa</Label>
                  </div>

                  <DialogFooter>
                    <Button 
                      type="button" 
                      variant="outline" 
                      onClick={() => setIsDialogOpen(false)}
                      data-testid="button-cancel"
                    >
                      Cancelar
                    </Button>
                    <Button 
                      type="submit" 
                      disabled={!formData.sourceName || createSource.isPending || updateSource.isPending}
                      data-testid="button-save-source"
                    >
                      {(createSource.isPending || updateSource.isPending) ? 'Guardando...' : 'Guardar'}
                    </Button>
                  </DialogFooter>
                </form>
              </DialogContent>
            </Dialog>
          </div>

          {/* Review Sources List */}
          <div className="space-y-4">
            {isLoading ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {[1, 2, 3].map((i) => (
                  <div key={i} className="h-48 bg-gray-200 rounded animate-pulse" />
                ))}
              </div>
            ) : reviewSources.length === 0 ? (
              <Card>
                <CardContent className="py-12">
                  <div className="text-center space-y-2">
                    <Settings className="h-12 w-12 text-muted-foreground mx-auto" />
                    <h3 className="text-lg font-semibold">No hay fuentes configuradas</h3>
                    <p className="text-muted-foreground">
                      Agrega tu primera fuente de reseñas para comenzar
                    </p>
                  </div>
                </CardContent>
              </Card>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {reviewSources.map((source) => (
                  <Card key={source.id} data-testid={`source-${source.id}`}>
                    <CardHeader className="pb-3">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          {getSourceIcon(source.sourceName)}
                          <div>
                            <CardTitle className="text-lg capitalize">
                              {source.sourceName}
                            </CardTitle>
                            <Badge variant={source.isActive ? 'default' : 'secondary'}>
                              {source.isActive ? 'Activa' : 'Inactiva'}
                            </Badge>
                          </div>
                        </div>
                        <div className="flex items-center gap-1">
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleEdit(source)}
                            data-testid={`button-edit-${source.id}`}
                          >
                            <Settings className="h-4 w-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleDelete(source.id)}
                            data-testid={`button-delete-${source.id}`}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                    </CardHeader>
                    <CardContent className="space-y-3">
                      <div className="grid grid-cols-2 gap-4 text-sm">
                        <div>
                          <span className="flex items-center gap-1 text-muted-foreground">
                            <Star className="h-3 w-3" />
                            Reseñas
                          </span>
                          <p className="font-semibold" data-testid={`total-reviews-${source.id}`}>
                            {source.totalReviews}
                          </p>
                        </div>
                        <div>
                          <span className="flex items-center gap-1 text-muted-foreground">
                            <BarChart3 className="h-3 w-3" />
                            Promedio
                          </span>
                          <p className="font-semibold" data-testid={`average-rating-${source.id}`}>
                            {source.averageRating ? `${source.averageRating}⭐` : 'N/A'}
                          </p>
                        </div>
                      </div>

                      <div className="text-sm">
                        <span className="flex items-center gap-1 text-muted-foreground">
                          <Calendar className="h-3 w-3" />
                          Última sincronización
                        </span>
                        <p data-testid={`last-sync-${source.id}`}>
                          {formatLastSync(source.lastSyncAt)}
                        </p>
                      </div>

                      <div className="text-sm">
                        <span className="text-muted-foreground">Frecuencia:</span>
                        <span className="ml-1">Cada {source.syncFrequency} horas</span>
                      </div>

                      {source.sourceUrl && (
                        <Button
                          size="sm"
                          variant="outline"
                          className="w-full"
                          onClick={() => window.open(source.sourceUrl!, '_blank')}
                          data-testid={`button-visit-${source.id}`}
                        >
                          <ExternalLink className="h-4 w-4 mr-2" />
                          Visitar
                        </Button>
                      )}
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

client/src/components/SubscriptionManage.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { 
  CreditCard, 
  Crown, 
  Calendar, 
  AlertCircle, 
  CheckCircle2,
  X,
  DollarSign
} from "lucide-react";
// API response types (dates come as strings from JSON)
interface SubscriptionPlanApi {
  id: string;
  name: string;
  description: string | null;
  price: string;
  currency: string;
  interval: string;
  features: string;
  maxLocations: number | null;
  maxUsers: number | null;
  isActive: boolean;
}

interface SubscriptionApi {
  id: string;
  planId: string;
  status: string;
  currentPeriodStart: string;
  currentPeriodEnd: string;
  cancelAtPeriodEnd: boolean;
  plan: SubscriptionPlanApi;
}

interface PaymentApi {
  id: string;
  amount: string;
  currency: string;
  status: string;
  paidAt: string | null;
  createdAt: string;
}

interface CreateSubscriptionResponse {
  checkoutUrl?: string;
  id: string;
  status: string;
}

export default function SubscriptionManager() {
  const { toast } = useToast();
  const [selectedPlan, setSelectedPlan] = useState<string | null>(null);

  // Get subscription plans
  const { data: plans = [], isLoading: plansLoading } = useQuery<SubscriptionPlanApi[]>({
    queryKey: ['/api/subscription-plans'],
  });

  // Get current user subscription
  const { data: subscription, isLoading: subscriptionLoading } = useQuery<SubscriptionApi | null>({
    queryKey: ['/api/users/subscription'],
  });

  // Get payment history
  const { data: payments = [], isLoading: paymentsLoading } = useQuery<PaymentApi[]>({
    queryKey: ['/api/users/payments'],
  });

  // Create subscription mutation
  const createSubscription = useMutation({
    mutationFn: async (planId: string) => {
      const response = await apiRequest('/api/subscriptions/create', {
        method: 'POST',
        data: { 
          planId,
          paymentMethodId: 'credit_card' // Mock payment method
        }
      });
      return await response.json() as CreateSubscriptionResponse;
    },
    onSuccess: (data) => {
      toast({
        title: "Suscripción Creada",
        description: "Redirigiendo a MercadoPago para completar el pago...",
      });

      // Redirect to MercadoPago checkout
      if (data?.checkoutUrl) {
        window.location.href = data.checkoutUrl;
      }

      queryClient.invalidateQueries({ queryKey: ['/api/users/subscription'] });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo crear la suscripción. Intenta de nuevo.",
        variant: "destructive",
      });
    },
  });

  // Cancel subscription mutation
  const cancelSubscription = useMutation({
    mutationFn: async (subscriptionId: string) => {
      const response = await apiRequest(`/api/subscriptions/${subscriptionId}/cancel`, {
        method: 'POST'
      });
      return await response.json();
    },
    onSuccess: () => {
      toast({
        title: "Suscripción Cancelada",
        description: "Tu suscripción se cancelará al final del período actual.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/users/subscription'] });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo cancelar la suscripción.",
        variant: "destructive",
      });
    },
  });

  const handleSubscribe = (planId: string) => {
    setSelectedPlan(planId);
    createSubscription.mutate(planId);
  };

  const handleCancel = () => {
    if (subscription?.id) {
      cancelSubscription.mutate(subscription.id);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('es-MX', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const getStatusBadge = (status: string) => {
    const statusMap = {
      active: { label: 'Activa', variant: 'default' as const },
      trialing: { label: 'Prueba Gratis', variant: 'secondary' as const },
      past_due: { label: 'Vencida', variant: 'destructive' as const },
      cancelled: { label: 'Cancelada', variant: 'outline' as const },
    };

    const statusInfo = statusMap[status as keyof typeof statusMap] || { label: status, variant: 'outline' as const };
    return <Badge variant={statusInfo.variant}>{statusInfo.label}</Badge>;
  };

  const getPaymentStatusIcon = (status: string) => {
    switch (status) {
      case 'approved':
        return <CheckCircle2 className="h-4 w-4 text-green-600" />;
      case 'pending':
        return <AlertCircle className="h-4 w-4 text-yellow-600" />;
      case 'rejected':
      case 'cancelled':
        return <X className="h-4 w-4 text-red-600" />;
      default:
        return <AlertCircle className="h-4 w-4 text-gray-600" />;
    }
  };

  if (plansLoading || subscriptionLoading) {
    return (
      <div className="space-y-6">
        <div className="h-8 bg-gray-200 rounded animate-pulse" />
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-64 bg-gray-200 rounded animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="subscription-manager">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight" data-testid="title-subscriptions">Suscripciones</h1>
          <p className="text-muted-foreground">
            Gestiona tu plan de suscripción y historial de pagos
          </p>
        </div>
      </div>

      {/* Current Subscription Status */}
      {subscription && (
        <Card data-testid="current-subscription">
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="flex items-center gap-2">
                <Crown className="h-5 w-5" />
                Suscripción Actual
              </CardTitle>
              {getStatusBadge(subscription?.status || '')}
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Plan</p>
                <p className="text-lg font-semibold">{subscription?.plan?.name}</p>
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Precio</p>
                <p className="text-lg font-semibold">
                  ${subscription?.plan?.price} {subscription?.plan?.currency}/{subscription?.plan?.interval === 'monthly' ? 'mes' : 'año'}
                </p>
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Próximo Pago</p>
                <p className="text-lg font-semibold">{formatDate(subscription?.currentPeriodEnd || '')}</p>
              </div>
            </div>

            {subscription?.plan?.description && (
              <p className="text-muted-foreground">{subscription.plan.description}</p>
            )}

            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4" />
                <span className="text-sm">
                  Período: {formatDate(subscription?.currentPeriodStart || '')} - {formatDate(subscription?.currentPeriodEnd || '')}
                </span>
              </div>
            </div>

            {subscription?.status === 'active' && !subscription?.cancelAtPeriodEnd && (
              <div className="pt-4 border-t">
                <Button 
                  variant="outline" 
                  onClick={handleCancel}
                  disabled={cancelSubscription.isPending}
                  data-testid="button-cancel-subscription"
                >
                  {cancelSubscription.isPending ? 'Cancelando...' : 'Cancelar Suscripción'}
                </Button>
              </div>
            )}

            {subscription?.cancelAtPeriodEnd && (
              <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                <div className="flex items-center gap-2">
                  <AlertCircle className="h-4 w-4 text-yellow-600" />
                  <span className="text-sm text-yellow-800">
                    Tu suscripción se cancelará el {formatDate(subscription?.currentPeriodEnd || '')}
                  </span>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Available Plans */}
      {(!subscription || subscription?.status === 'cancelled') && (
        <div>
          <h2 className="text-2xl font-bold mb-4" data-testid="title-available-plans">Planes Disponibles</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {plans.map((plan: SubscriptionPlanApi) => (
              <Card key={plan.id} className={`relative ${selectedPlan === plan.id ? 'ring-2 ring-primary' : ''}`} data-testid={`plan-${plan.id}`}>
                <CardHeader>
                  <CardTitle>{plan.name}</CardTitle>
                  <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold">${plan.price}</span>
                    <span className="text-muted-foreground">
                      {plan.currency}/{plan.interval === 'monthly' ? 'mes' : 'año'}
                    </span>
                  </div>
                  {plan.description && (
                    <p className="text-sm text-muted-foreground">{plan.description}</p>
                  )}
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-2">
                    {JSON.parse(plan.features || '[]').map((feature: string, index: number) => (
                      <div key={index} className="flex items-center gap-2">
                        <CheckCircle2 className="h-4 w-4 text-green-600" />
                        <span className="text-sm">{feature}</span>
                      </div>
                    ))}
                  </div>

                  <Separator />

                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <span className="font-medium">Ubicaciones:</span>
                      <span className="ml-1">{plan.maxLocations || 'Ilimitadas'}</span>
                    </div>
                    <div>
                      <span className="font-medium">Usuarios:</span>
                      <span className="ml-1">{plan.maxUsers || 'Ilimitados'}</span>
                    </div>
                  </div>

                  <Button 
                    className="w-full"
                    onClick={() => handleSubscribe(plan.id)}
                    disabled={createSubscription.isPending && selectedPlan === plan.id}
                    data-testid={`button-subscribe-${plan.id}`}
                  >
                    {createSubscription.isPending && selectedPlan === plan.id ? (
                      'Procesando...'
                    ) : (
                      'Suscribirse'
                    )}
                  </Button>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      )}

      {/* Payment History */}
      <Card data-testid="payment-history">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CreditCard className="h-5 w-5" />
            Historial de Pagos
          </CardTitle>
        </CardHeader>
        <CardContent>
          {paymentsLoading ? (
            <div className="space-y-2">
              {[1, 2, 3].map((i) => (
                <div key={i} className="h-16 bg-gray-200 rounded animate-pulse" />
              ))}
            </div>
          ) : payments.length === 0 ? (
            <p className="text-muted-foreground text-center py-8">
              No hay pagos registrados
            </p>
          ) : (
            <div className="space-y-4">
              {payments.map((payment: PaymentApi) => (
                <div key={payment.id} className="flex items-center justify-between p-4 border rounded-lg" data-testid={`payment-${payment.id}`}>
                  <div className="flex items-center gap-3">
                    {getPaymentStatusIcon(payment.status)}
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-medium">${payment.amount || '0'} {payment.currency || 'MXN'}</span>
                        <Badge variant={payment.status === 'approved' ? 'default' : 'secondary'}>
                          {payment.status === 'approved' ? 'Aprobado' : payment.status}
                        </Badge>
                      </div>
                      <p className="text-sm text-muted-foreground">
                        {payment.paidAt ? formatDate(payment.paidAt) : formatDate(payment.createdAt || '')}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <DollarSign className="h-4 w-4 text-muted-foreground" />
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/GmbPostCreator.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { 
  Plus, 
  Calendar, 
  MapPin, 
  Edit2,
  Trash2,
  Send,
  Eye,
  BarChart3,
  Clock,
  CheckCircle2
} from "lucide-react";
import type { GmbPost, Location } from "@shared/schema";

const createGmbPostSchema = z.object({
  title: z.string().max(255).optional(),
  content: z.string().min(1, "El contenido es requerido").max(1500),
  postType: z.enum(["offer", "event", "product", "standard"]).default("standard"),
  callToAction: z.enum(["learn_more", "call", "order", "book"]).optional(),
  buttonUrl: z.string().url("URL válida requerida").optional().or(z.literal("")),
  imageUrl: z.string().url("URL válida requerida").optional().or(z.literal("")),
  scheduledDate: z.string().optional()
});

type GmbPostForm = z.infer<typeof createGmbPostSchema>;

export default function GmbPostCreator() {
  const { toast } = useToast();
  const [selectedLocation, setSelectedLocation] = useState<string>("");
  const [editingPost, setEditingPost] = useState<GmbPost | null>(null);

  const form = useForm<GmbPostForm>({
    resolver: zodResolver(createGmbPostSchema),
    defaultValues: {
      title: "",
      content: "",
      postType: "standard",
      callToAction: undefined,
      buttonUrl: "",
      imageUrl: "",
      scheduledDate: ""
    }
  });

  // Get locations
  const { data: locations = [] } = useQuery<Location[]>({
    queryKey: ['/api/businesses/locations'],
  });

  // Get GMB posts for selected location
  const { data: gmbPosts = [], isLoading, refetch } = useQuery<GmbPost[]>({
    queryKey: ['/api/locations', selectedLocation, 'gmb-posts'],
    enabled: !!selectedLocation,
  });

  // Create GMB post mutation
  const createPost = useMutation({
    mutationFn: async (data: GmbPostForm) => {
      const response = await apiRequest(`/api/locations/${selectedLocation}/gmb-posts`, {
        method: 'POST',
        data
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Post Creado",
        description: "El post de Google My Business se creó correctamente.",
      });
      form.reset();
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo crear el post de GMB.",
        variant: "destructive",
      });
    },
  });

  // Update GMB post mutation
  const updatePost = useMutation({
    mutationFn: async ({ postId, data }: { postId: string; data: Partial<GmbPostForm> }) => {
      const response = await apiRequest(`/api/gmb-posts/${postId}`, {
        method: 'PUT',
        data
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Post Actualizado",
        description: "El post se actualizó correctamente.",
      });
      setEditingPost(null);
      form.reset();
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo actualizar el post.",
        variant: "destructive",
      });
    },
  });

  // Publish GMB post mutation
  const publishPost = useMutation({
    mutationFn: async (postId: string) => {
      const response = await apiRequest(`/api/gmb-posts/${postId}/publish`, {
        method: 'POST'
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Post Publicado",
        description: "El post se publicó en Google My Business.",
      });
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo publicar el post.",
        variant: "destructive",
      });
    },
  });

  // Delete GMB post mutation
  const deletePost = useMutation({
    mutationFn: async (postId: string) => {
      await apiRequest(`/api/gmb-posts/${postId}`, {
        method: 'DELETE'
      });
    },
    onSuccess: () => {
      toast({
        title: "Post Eliminado",
        description: "El post se eliminó correctamente.",
      });
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo eliminar el post.",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (data: GmbPostForm) => {
    if (editingPost) {
      updatePost.mutate({ postId: editingPost.id, data });
    } else {
      createPost.mutate(data);
    }
  };

  const handleEdit = (post: GmbPost) => {
    setEditingPost(post);
    form.reset({
      title: post.title || "",
      content: post.content,
      postType: post.postType as "offer" | "event" | "product" | "standard",
      callToAction: post.callToAction as "learn_more" | "call" | "order" | "book" | undefined,
      buttonUrl: post.buttonUrl || "",
      imageUrl: post.imageUrl || "",
      scheduledDate: post.scheduledDate ? new Date(post.scheduledDate).toISOString().slice(0, 16) : ""
    });
  };

  const handleCancelEdit = () => {
    setEditingPost(null);
    form.reset();
  };

  const handleDelete = (postId: string) => {
    if (confirm('¿Estás seguro de que quieres eliminar este post?')) {
      deletePost.mutate(postId);
    }
  };

  const getStatusBadge = (status: string) => {
    const statusMap = {
      draft: { label: 'Borrador', variant: 'secondary' as const },
      scheduled: { label: 'Programado', variant: 'default' as const },
      published: { label: 'Publicado', variant: 'default' as const },
      failed: { label: 'Error', variant: 'destructive' as const },
    };

    const statusInfo = statusMap[status as keyof typeof statusMap] || { label: status, variant: 'outline' as const };
    return <Badge variant={statusInfo.variant}>{statusInfo.label}</Badge>;
  };

  const getPostTypeLabel = (type: string) => {
    const typeMap = {
      standard: 'Estándar',
      offer: 'Oferta',
      event: 'Evento',
      product: 'Producto'
    };
    return typeMap[type as keyof typeof typeMap] || type;
  };

  const formatDate = (date: string | Date) => {
    const dateObj = typeof date === 'string' ? new Date(date) : date;
    return dateObj.toLocaleDateString('es-MX', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-6" data-testid="gmb-post-creator">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight" data-testid="title-gmb-posts">Posts de Google My Business</h1>
          <p className="text-muted-foreground">
            Crea y gestiona posts para tu perfil de Google My Business
          </p>
        </div>
      </div>

      {/* Location Selector */}
      <Card data-testid="location-selector">
        <CardHeader>
          <CardTitle>Seleccionar Ubicación</CardTitle>
        </CardHeader>
        <CardContent>
          <Select value={selectedLocation} onValueChange={setSelectedLocation}>
            <SelectTrigger data-testid="select-location">
              <SelectValue placeholder="Selecciona una ubicación" />
            </SelectTrigger>
            <SelectContent>
              {locations.map((location) => (
                <SelectItem key={location.id} value={location.id}>
                  {location.name} - {location.city}, {location.state}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {selectedLocation && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Create/Edit Post Form */}
          <Card data-testid="post-form">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Plus className="h-5 w-5" />
                {editingPost ? 'Editar Post' : 'Crear Nuevo Post'}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="title">Título (Opcional)</Label>
                  <Input
                    id="title"
                    {...form.register("title")}
                    placeholder="Título del post"
                    data-testid="input-title"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="content">Contenido *</Label>
                  <Textarea
                    id="content"
                    {...form.register("content")}
                    placeholder="Escribe el contenido de tu post..."
                    rows={4}
                    data-testid="textarea-content"
                  />
                  {form.formState.errors.content && (
                    <p className="text-sm text-red-600">{form.formState.errors.content.message}</p>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="postType">Tipo de Post</Label>
                    <Select 
                      value={form.watch("postType")} 
                      onValueChange={(value) => form.setValue("postType", value as any)}
                    >
                      <SelectTrigger data-testid="select-post-type">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="standard">Estándar</SelectItem>
                        <SelectItem value="offer">Oferta</SelectItem>
                        <SelectItem value="event">Evento</SelectItem>
                        <SelectItem value="product">Producto</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="callToAction">Llamada a la Acción</Label>
                    <Select 
                      value={form.watch("callToAction") || ""} 
                      onValueChange={(value) => form.setValue("callToAction", value as any)}
                    >
                      <SelectTrigger data-testid="select-call-to-action">
                        <SelectValue placeholder="Seleccionar" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="">Ninguna</SelectItem>
                        <SelectItem value="learn_more">Saber Más</SelectItem>
                        <SelectItem value="call">Llamar</SelectItem>
                        <SelectItem value="order">Ordenar</SelectItem>
                        <SelectItem value="book">Reservar</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="buttonUrl">URL del Botón (Opcional)</Label>
                  <Input
                    id="buttonUrl"
                    type="url"
                    {...form.register("buttonUrl")}
                    placeholder="https://ejemplo.com"
                    data-testid="input-button-url"
                  />
                  {form.formState.errors.buttonUrl && (
                    <p className="text-sm text-red-600">{form.formState.errors.buttonUrl.message}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="imageUrl">URL de Imagen (Opcional)</Label>
                  <Input
                    id="imageUrl"
                    type="url"
                    {...form.register("imageUrl")}
                    placeholder="https://ejemplo.com/imagen.jpg"
                    data-testid="input-image-url"
                  />
                  {form.formState.errors.imageUrl && (
                    <p className="text-sm text-red-600">{form.formState.errors.imageUrl.message}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="scheduledDate">Fecha de Programación (Opcional)</Label>
                  <Input
                    id="scheduledDate"
                    type="datetime-local"
                    {...form.register("scheduledDate")}
                    data-testid="input-scheduled-date"
                  />
                </div>

                <div className="flex gap-2 pt-4">
                  <Button 
                    type="submit" 
                    disabled={createPost.isPending || updatePost.isPending}
                    data-testid="button-save-post"
                  >
                    {createPost.isPending || updatePost.isPending ? (
                      'Guardando...'
                    ) : editingPost ? (
                      'Actualizar Post'
                    ) : (
                      'Crear Post'
                    )}
                  </Button>

                  {editingPost && (
                    <Button 
                      type="button" 
                      variant="outline" 
                      onClick={handleCancelEdit}
                      data-testid="button-cancel-edit"
                    >
                      Cancelar
                    </Button>
                  )}
                </div>
              </form>
            </CardContent>
          </Card>

          {/* Posts List */}
          <Card data-testid="posts-list">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <MapPin className="h-5 w-5" />
                Posts Creados
              </CardTitle>
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <div className="space-y-4">
                  {[1, 2, 3].map((i) => (
                    <div key={i} className="h-24 bg-gray-200 rounded animate-pulse" />
                  ))}
                </div>
              ) : gmbPosts.length === 0 ? (
                <div className="text-center py-8 space-y-2">
                  <MapPin className="h-12 w-12 text-muted-foreground mx-auto" />
                  <h3 className="text-lg font-semibold">No hay posts creados</h3>
                  <p className="text-muted-foreground">
                    Crea tu primer post para Google My Business
                  </p>
                </div>
              ) : (
                <div className="space-y-4 max-h-96 overflow-y-auto">
                  {gmbPosts.map((post) => (
                    <div key={post.id} className="border rounded-lg p-4 space-y-3" data-testid={`post-${post.id}`}>
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            {getStatusBadge(post.status)}
                            <Badge variant="outline">{getPostTypeLabel(post.postType)}</Badge>
                          </div>
                          {post.title && (
                            <h4 className="font-semibold mb-1" data-testid={`post-title-${post.id}`}>
                              {post.title}
                            </h4>
                          )}
                          <p className="text-sm text-muted-foreground line-clamp-2" data-testid={`post-content-${post.id}`}>
                            {post.content}
                          </p>
                        </div>
                        <div className="flex items-center gap-1">
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleEdit(post)}
                            data-testid={`button-edit-${post.id}`}
                          >
                            <Edit2 className="h-4 w-4" />
                          </Button>
                          {post.status === 'draft' && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => publishPost.mutate(post.id)}
                              disabled={publishPost.isPending}
                              data-testid={`button-publish-${post.id}`}
                            >
                              <Send className="h-4 w-4" />
                            </Button>
                          )}
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleDelete(post.id)}
                            data-testid={`button-delete-${post.id}`}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>

                      {/* Post metadata */}
                      <div className="flex items-center gap-4 text-xs text-muted-foreground">
                        {post.scheduledDate && (
                          <div className="flex items-center gap-1">
                            <Calendar className="h-3 w-3" />
                            <span>Programado: {formatDate(post.scheduledDate)}</span>
                          </div>
                        )}
                        {post.publishedDate && (
                          <div className="flex items-center gap-1">
                            <CheckCircle2 className="h-3 w-3" />
                            <span>Publicado: {formatDate(post.publishedDate)}</span>
                          </div>
                        )}
                        {post.status === 'published' && (
                          <div className="flex items-center gap-3">
                            <div className="flex items-center gap-1">
                              <Eye className="h-3 w-3" />
                              <span>{post.views} vistas</span>
                            </div>
                            <div className="flex items-center gap-1">
                              <BarChart3 className="h-3 w-3" />
                              <span>{post.clicks} clics</span>
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

client/src/components/TrialSignup.tsx.content:
import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { 
  Rocket, 
  CheckCircle2, 
  Clock, 
  Star,
  Globe,
  Users,
  Zap
} from "lucide-react";

const trialSignupSchema = z.object({
  businessName: z.string().min(1, "Nombre del negocio es requerido").max(255),
  contactEmail: z.string().email("Email válido es requerido"),
  phone: z.string().max(20).optional(),
  industry: z.string().max(100).optional(),
  city: z.string().max(100).optional(),
  websiteUrl: z.string().url("URL válida requerida").optional().or(z.literal("")),
  currentReviewPlatforms: z.array(z.string()).optional(),
  mainChallenges: z.string().max(1000).optional(),
  heardAboutUs: z.string().max(100).optional(),
  acceptTerms: z.boolean().refine(val => val, "Debes aceptar los términos y condiciones")
});

type TrialSignupForm = z.infer<typeof trialSignupSchema>;

export default function TrialSignup() {
  const { toast } = useToast();
  const [selectedPlatforms, setSelectedPlatforms] = useState<string[]>([]);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const form = useForm<TrialSignupForm>({
    resolver: zodResolver(trialSignupSchema),
    defaultValues: {
      businessName: "",
      contactEmail: "",
      phone: "",
      industry: "",
      city: "",
      websiteUrl: "",
      currentReviewPlatforms: [],
      mainChallenges: "",
      heardAboutUs: "",
      acceptTerms: false
    }
  });

  const signupMutation = useMutation({
    mutationFn: async (data: TrialSignupForm) => {
      const response = await apiRequest('/api/trial-signup', {
        method: 'POST',
        data: {
          ...data,
          currentReviewPlatforms: selectedPlatforms
        }
      });
      return response;
    },
    onSuccess: () => {
      setIsSubmitted(true);
      toast({
        title: "¡Registro Exitoso!",
        description: "Tu prueba gratis de 14 días ha comenzado. Revisa tu email para más información.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "No se pudo procesar tu registro. Intenta de nuevo.",
        variant: "destructive",
      });
    },
  });

  const reviewPlatforms = [
    { id: 'google', label: 'Google My Business' },
    { id: 'facebook', label: 'Facebook' },
    { id: 'tripadvisor', label: 'TripAdvisor' },
    { id: 'yelp', label: 'Yelp' },
    { id: 'other', label: 'Otros' }
  ];

  const industries = [
    'Restaurantes y Comida',
    'Salud y Bienestar',
    'Belleza y Estética',
    'Retail y Comercio',
    'Servicios Profesionales',
    'Turismo y Hotelería',
    'Automotriz',
    'Inmobiliaria',
    'Tecnología',
    'Otro'
  ];

  const hearAboutUsOptions = [
    'Búsqueda en Google',
    'Redes Sociales',
    'Recomendación',
    'Publicidad Online',
    'Otro'
  ];

  const handlePlatformChange = (platformId: string, checked: boolean) => {
    if (checked) {
      setSelectedPlatforms(prev => [...prev, platformId]);
    } else {
      setSelectedPlatforms(prev => prev.filter(id => id !== platformId));
    }
  };

  const onSubmit = (data: TrialSignupForm) => {
    signupMutation.mutate(data);
  };

  if (isSubmitted) {
    return (
      <div className="max-w-2xl mx-auto space-y-6" data-testid="trial-success">
        <Card>
          <CardContent className="py-12">
            <div className="text-center space-y-4">
              <div className="flex justify-center">
                <div className="p-3 bg-green-100 rounded-full">
                  <CheckCircle2 className="h-12 w-12 text-green-600" />
                </div>
              </div>
              <h2 className="text-3xl font-bold" data-testid="title-success">¡Registro Exitoso!</h2>
              <p className="text-lg text-muted-foreground">
                Tu prueba gratis de 14 días ha comenzado
              </p>
              <div className="space-y-2">
                <p className="text-sm text-muted-foreground">
                  Hemos enviado un email de bienvenida a tu correo con los siguientes pasos.
                </p>
                <p className="text-sm text-muted-foreground">
                  También hemos notificado a nuestro equipo para que puedan ayudarte a sacar el máximo provecho de Altevia.
                </p>
              </div>
              <div className="pt-4">
                <Button onClick={() => window.location.href = '/dashboard'} data-testid="button-go-dashboard">
                  Ir al Dashboard
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6" data-testid="trial-signup">
      {/* Hero Section */}
      <div className="text-center space-y-4 py-8">
        <div className="flex justify-center">
          <div className="p-3 bg-primary/10 rounded-full">
            <Rocket className="h-12 w-12 text-primary" />
          </div>
        </div>
        <h1 className="text-4xl font-bold tracking-tight" data-testid="title-trial">
          Comienza tu Prueba Gratis de 14 Días
        </h1>
        <p className="text-xl text-muted-foreground max-w-2xl mx-auto">
          Mejora la visibilidad digital de tu negocio con herramientas de IA para SEO, gestión de reseñas y análisis de competencia
        </p>
      </div>

      {/* Features Preview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <Card>
          <CardContent className="p-6 text-center">
            <Zap className="h-8 w-8 text-primary mx-auto mb-2" />
            <h3 className="font-semibold mb-2">IA para SEO Local</h3>
            <p className="text-sm text-muted-foreground">
              Genera contenido optimizado para tu ubicación automáticamente
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6 text-center">
            <Star className="h-8 w-8 text-primary mx-auto mb-2" />
            <h3 className="font-semibold mb-2">Gestión de Reseñas</h3>
            <p className="text-sm text-muted-foreground">
              Respuestas inteligentes y monitoreo automático de reputación
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6 text-center">
            <Users className="h-8 w-8 text-primary mx-auto mb-2" />
            <h3 className="font-semibold mb-2">Análisis de Competencia</h3>
            <p className="text-sm text-muted-foreground">
              Conoce cómo te comparas con tu competencia local
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Signup Form */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Globe className="h-5 w-5" />
            Información de tu Negocio
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="businessName">Nombre del Negocio *</Label>
                <Input
                  id="businessName"
                  {...form.register("businessName")}
                  placeholder="Ej: Restaurante La Vista"
                  data-testid="input-business-name"
                />
                {form.formState.errors.businessName && (
                  <p className="text-sm text-red-600">{form.formState.errors.businessName.message}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="contactEmail">Email de Contacto *</Label>
                <Input
                  id="contactEmail"
                  type="email"
                  {...form.register("contactEmail")}
                  placeholder="contacto@negocio.com"
                  data-testid="input-contact-email"
                />
                {form.formState.errors.contactEmail && (
                  <p className="text-sm text-red-600">{form.formState.errors.contactEmail.message}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="phone">Teléfono</Label>
                <Input
                  id="phone"
                  {...form.register("phone")}
                  placeholder="+52 55 1234 5678"
                  data-testid="input-phone"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="city">Ciudad</Label>
                <Input
                  id="city"
                  {...form.register("city")}
                  placeholder="Ciudad de México"
                  data-testid="input-city"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="industry">Industria</Label>
                <select
                  id="industry"
                  {...form.register("industry")}
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                  data-testid="select-industry"
                >
                  <option value="">Selecciona una industria</option>
                  {industries.map((industry) => (
                    <option key={industry} value={industry}>{industry}</option>
                  ))}
                </select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="websiteUrl">Sitio Web</Label>
                <Input
                  id="websiteUrl"
                  type="url"
                  {...form.register("websiteUrl")}
                  placeholder="https://www.negocio.com"
                  data-testid="input-website-url"
                />
                {form.formState.errors.websiteUrl && (
                  <p className="text-sm text-red-600">{form.formState.errors.websiteUrl.message}</p>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <Label>¿En qué plataformas tienes reseñas actualmente?</Label>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {reviewPlatforms.map((platform) => (
                  <div key={platform.id} className="flex items-center space-x-2">
                    <Checkbox
                      id={platform.id}
                      checked={selectedPlatforms.includes(platform.id)}
                      onCheckedChange={(checked) => handlePlatformChange(platform.id, !!checked)}
                      data-testid={`checkbox-platform-${platform.id}`}
                    />
                    <Label htmlFor={platform.id} className="text-sm">
                      {platform.label}
                    </Label>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="mainChallenges">¿Cuáles son tus principales desafíos con la visibilidad online?</Label>
              <Textarea
                id="mainChallenges"
                {...form.register("mainChallenges")}
                placeholder="Ej: Pocas reseñas online, baja visibilidad en Google, competencia fuerte..."
                rows={3}
                data-testid="textarea-main-challenges"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="heardAboutUs">¿Cómo supiste de Altevia?</Label>
              <select
                id="heardAboutUs"
                {...form.register("heardAboutUs")}
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                data-testid="select-heard-about-us"
              >
                <option value="">Selecciona una opción</option>
                {hearAboutUsOptions.map((option) => (
                  <option key={option} value={option}>{option}</option>
                ))}
              </select>
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox
                id="acceptTerms"
                {...form.register("acceptTerms")}
                data-testid="checkbox-accept-terms"
              />
              <Label htmlFor="acceptTerms" className="text-sm">
                Acepto los{" "}
                <a href="/terms" target="_blank" className="text-primary hover:underline">
                  términos y condiciones
                </a>{" "}
                y la{" "}
                <a href="/privacy" target="_blank" className="text-primary hover:underline">
                  política de privacidad
                </a>
              </Label>
            </div>
            {form.formState.errors.acceptTerms && (
              <p className="text-sm text-red-600">{form.formState.errors.acceptTerms.message}</p>
            )}

            <div className="border-t pt-6">
              <div className="flex items-center gap-4 mb-4">
                <Clock className="h-5 w-5 text-primary" />
                <div>
                  <p className="font-semibold">14 días gratis, sin compromiso</p>
                  <p className="text-sm text-muted-foreground">
                    Cancela en cualquier momento. No se requiere tarjeta de crédito.
                  </p>
                </div>
              </div>

              <Button 
                type="submit" 
                className="w-full" 
                size="lg"
                disabled={signupMutation.isPending}
                data-testid="button-start-trial"
              >
                {signupMutation.isPending ? (
                  'Procesando...'
                ) : (
                  'Comenzar Prueba Gratis'
                )}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

