import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { 
  Shield, 
  Users, 
  CreditCard, 
  Building,
  MapPin,
  TrendingUp,
  DollarSign,
  Clock,
  UserCheck,
  AlertTriangle,
  BarChart3,
  Calendar,
  LogOut
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

const adminLoginSchema = z.object({
  username: z.string().min(1, "Usuario es requerido"),
  password: z.string().min(1, "Contraseña es requerida")
});

type AdminLoginForm = z.infer<typeof adminLoginSchema>;

interface AdminStats {
  userCount: number;
  businessCount: number;
  locationCount: number;
  activeSubscriptionCount: number;
  trialSignupCount: number;
  monthlyRevenue: number;
  totalRevenue: number;
}

interface TrialSignup {
  id: string;
  businessName: string;
  contactEmail: string;
  phone: string | null;
  industry: string | null;
  city: string | null;
  websiteUrl: string | null;
  mainChallenges: string | null;
  trialStartDate: string;
  trialEndDate: string;
  status: string;
  notifiedAdmin: boolean;
  createdAt: string;
}

export default function AdminDashboard() {
  const { toast } = useToast();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isCheckingAuth, setIsCheckingAuth] = useState(true);
  const [showTrialDetails, setShowTrialDetails] = useState(false);
  const [currentUser, setCurrentUser] = useState<{id: string, username: string} | null>(null);

  const form = useForm<AdminLoginForm>({
    resolver: zodResolver(adminLoginSchema),
    defaultValues: {
      username: "",
      password: ""
    }
  });

  // Check authentication status on load
  useEffect(() => {
    const checkAuthStatus = async () => {
      try {
        const response = await apiRequest('/api/admin/verify');
        const data = await response.json();
        setIsAuthenticated(true);
        setCurrentUser(data.user);
      } catch (error) {
        setIsAuthenticated(false);
        setCurrentUser(null);
      } finally {
        setIsCheckingAuth(false);
      }
    };

    checkAuthStatus();
  }, []);

  // Admin login mutation
  const loginMutation = useMutation({
    mutationFn: async (data: AdminLoginForm) => {
      const response = await apiRequest('/api/admin/login', {
        method: 'POST',
        data
      });
      return response.json();
    },
    onSuccess: (data) => {
      setIsAuthenticated(true);
      setCurrentUser(data.user);
      queryClient.invalidateQueries();
      toast({
        title: "Acceso Autorizado",
        description: "Bienvenido al panel de administración.",
      });
    },
    onError: () => {
      toast({
        title: "Error de Autenticación",
        description: "Usuario o contraseña incorrectos.",
        variant: "destructive",
      });
    },
  });

  // Admin logout mutation
  const logoutMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest('/api/admin/logout', {
        method: 'POST'
      });
      return response.json();
    },
    onSuccess: () => {
      setIsAuthenticated(false);
      setCurrentUser(null);
      queryClient.clear();
      toast({
        title: "Sesión Cerrada",
        description: "Has cerrado sesión correctamente.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Error al cerrar sesión.",
        variant: "destructive",
      });
    },
  });

  // Get admin statistics
  const { data: statsResponse, isLoading: statsLoading } = useQuery<{stats: AdminStats}>({
    queryKey: ['/api/admin/stats'],
    enabled: isAuthenticated,
  });

  // Get trial signups
  const { data: signupsResponse, isLoading: trialsLoading } = useQuery<{signups: TrialSignup[]}>({
    queryKey: ['/api/admin/trial-signups'],
    enabled: isAuthenticated,
  });

  const stats = statsResponse?.stats;
  const trialSignups = signupsResponse?.signups || [];

  const handleLogin = (data: AdminLoginForm) => {
    loginMutation.mutate(data);
  };

  const handleLogout = () => {
    logoutMutation.mutate();
  };

  // Show loading while checking authentication
  if (isCheckingAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50" data-testid="admin-loading">
        <Card className="w-full max-w-md">
          <CardContent className="flex items-center justify-center p-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
            <span className="ml-2">Verificando autenticación...</span>
          </CardContent>
        </Card>
      </div>
    );
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('es-MX', {
      style: 'currency',
      currency: 'MXN'
    }).format(amount);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('es-MX', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const getStatusBadge = (status: string) => {
    const statusMap = {
      active: { label: 'Activo', variant: 'default' as const },
      expired: { label: 'Expirado', variant: 'destructive' as const },
      converted: { label: 'Convertido', variant: 'secondary' as const },
    };

    const statusInfo = statusMap[status as keyof typeof statusMap] || { label: status, variant: 'outline' as const };
    return <Badge variant={statusInfo.variant}>{statusInfo.label}</Badge>;
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50" data-testid="admin-login">
        <Card className="w-full max-w-md">
          <CardHeader className="text-center space-y-4">
            <div className="flex justify-center">
              <div className="p-3 bg-primary/10 rounded-full">
                <Shield className="h-8 w-8 text-primary" />
              </div>
            </div>
            <div>
              <CardTitle className="text-2xl" data-testid="title-admin-login">Panel de Administración</CardTitle>
              <p className="text-muted-foreground">Acceso restringido - Solo administradores</p>
            </div>
          </CardHeader>
          <CardContent>
            <form onSubmit={form.handleSubmit(handleLogin)} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="username">Usuario</Label>
                <Input
                  id="username"
                  {...form.register("username")}
                  placeholder="Ingresa tu usuario"
                  data-testid="input-username"
                />
                {form.formState.errors.username && (
                  <p className="text-sm text-red-600">{form.formState.errors.username.message}</p>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="password">Contraseña</Label>
                <Input
                  id="password"
                  type="password"
                  {...form.register("password")}
                  placeholder="Ingresa tu contraseña"
                  data-testid="input-password"
                />
                {form.formState.errors.password && (
                  <p className="text-sm text-red-600">{form.formState.errors.password.message}</p>
                )}
              </div>

              <Button 
                type="submit" 
                className="w-full" 
                disabled={loginMutation.isPending}
                data-testid="button-login"
              >
                {loginMutation.isPending ? 'Verificando...' : 'Iniciar Sesión'}
              </Button>
            </form>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-6" data-testid="admin-dashboard">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight" data-testid="title-admin-dashboard">Panel de Administración</h1>
          <p className="text-muted-foreground">
            Gestión y estadísticas del sistema Altevia
          </p>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Shield className="h-5 w-5 text-green-600" />
            <span className="text-sm text-green-600">Administrador: {currentUser?.username}</span>
          </div>
          <Button 
            variant="outline" 
            size="sm" 
            onClick={handleLogout}
            disabled={logoutMutation.isPending}
            data-testid="button-logout"
          >
            <LogOut className="h-4 w-4 mr-2" />
            {logoutMutation.isPending ? 'Cerrando...' : 'Cerrar Sesión'}
          </Button>
        </div>
      </div>

      {/* Statistics Overview */}
      {statsLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
            <div key={i} className="h-32 bg-gray-200 rounded animate-pulse" />
          ))}
        </div>
      ) : stats && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <Card data-testid="stat-users">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Usuarios</CardTitle>
              <Users className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="count-users">{stats.userCount}</div>
              <p className="text-xs text-muted-foreground">Usuarios registrados</p>
            </CardContent>
          </Card>

          <Card data-testid="stat-businesses">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Negocios</CardTitle>
              <Building className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="count-businesses">{stats.businessCount}</div>
              <p className="text-xs text-muted-foreground">Negocios creados</p>
            </CardContent>
          </Card>

          <Card data-testid="stat-locations">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Ubicaciones</CardTitle>
              <MapPin className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="count-locations">{stats.locationCount}</div>
              <p className="text-xs text-muted-foreground">Ubicaciones totales</p>
            </CardContent>
          </Card>

          <Card data-testid="stat-subscriptions">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Suscripciones Activas</CardTitle>
              <UserCheck className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="count-subscriptions">{stats.activeSubscriptionCount}</div>
              <p className="text-xs text-muted-foreground">Clientes pagando</p>
            </CardContent>
          </Card>

          <Card data-testid="stat-trials">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Pruebas Gratis</CardTitle>
              <Clock className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="count-trials">{stats.trialSignupCount}</div>
              <p className="text-xs text-muted-foreground">Usuarios en prueba</p>
            </CardContent>
          </Card>

          <Card data-testid="stat-monthly-revenue">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Ingresos del Mes</CardTitle>
              <TrendingUp className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="amount-monthly-revenue">
                {formatCurrency(stats.monthlyRevenue)}
              </div>
              <p className="text-xs text-muted-foreground">Mes actual</p>
            </CardContent>
          </Card>

          <Card data-testid="stat-total-revenue">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Ingresos Totales</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="amount-total-revenue">
                {formatCurrency(stats.totalRevenue)}
              </div>
              <p className="text-xs text-muted-foreground">Histórico</p>
            </CardContent>
          </Card>

          <Card data-testid="stat-conversion">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Tasa de Conversión</CardTitle>
              <BarChart3 className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold" data-testid="conversion-rate">
                {stats.trialSignupCount > 0 
                  ? Math.round((stats.activeSubscriptionCount / stats.trialSignupCount) * 100)
                  : 0}%
              </div>
              <p className="text-xs text-muted-foreground">Prueba a pago</p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Trial Signups Management */}
      <Card data-testid="trial-signups-section">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <Calendar className="h-5 w-5" />
              Solicitudes de Prueba Gratis
            </CardTitle>
            <Dialog open={showTrialDetails} onOpenChange={setShowTrialDetails}>
              <DialogTrigger asChild>
                <Button variant="outline" data-testid="button-view-trial-details">
                  Ver Detalles
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-4xl max-h-[80vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle>Detalles de Solicitudes de Prueba</DialogTitle>
                  <DialogDescription>
                    Información completa de todas las solicitudes de prueba gratis
                  </DialogDescription>
                </DialogHeader>

                {trialsLoading ? (
                  <div className="space-y-4">
                    {[1, 2, 3].map((i) => (
                      <div key={i} className="h-24 bg-gray-200 rounded animate-pulse" />
                    ))}
                  </div>
                ) : (
                  <div className="space-y-4">
                    {trialSignups.map((trial) => (
                      <Card key={trial.id} data-testid={`trial-${trial.id}`}>
                        <CardHeader className="pb-3">
                          <div className="flex items-center justify-between">
                            <div>
                              <CardTitle className="text-lg">{trial.businessName}</CardTitle>
                              <p className="text-sm text-muted-foreground">{trial.contactEmail}</p>
                            </div>
                            <div className="flex items-center gap-2">
                              {getStatusBadge(trial.status)}
                              {!trial.notifiedAdmin && (
                                <AlertTriangle className="h-4 w-4 text-yellow-600" />
                              )}
                            </div>
                          </div>
                        </CardHeader>
                        <CardContent className="space-y-3">
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
                            {trial.phone && (
                              <div>
                                <span className="font-medium">Teléfono:</span>
                                <p>{trial.phone}</p>
                              </div>
                            )}
                            {trial.industry && (
                              <div>
                                <span className="font-medium">Industria:</span>
                                <p>{trial.industry}</p>
                              </div>
                            )}
                            {trial.city && (
                              <div>
                                <span className="font-medium">Ciudad:</span>
                                <p>{trial.city}</p>
                              </div>
                            )}
                          </div>

                          {trial.websiteUrl && (
                            <div className="text-sm">
                              <span className="font-medium">Sitio web:</span>
                              <a 
                                href={trial.websiteUrl} 
                                target="_blank" 
                                className="text-primary hover:underline ml-1"
                              >
                                {trial.websiteUrl}
                              </a>
                            </div>
                          )}

                          {trial.mainChallenges && (
                            <div className="text-sm">
                              <span className="font-medium">Principales desafíos:</span>
                              <p className="mt-1 text-muted-foreground">{trial.mainChallenges}</p>
                            </div>
                          )}

                          <div className="grid grid-cols-2 gap-4 text-sm pt-2 border-t">
                            <div>
                              <span className="font-medium">Inicio de prueba:</span>
                              <p>{formatDate(trial.trialStartDate)}</p>
                            </div>
                            <div>
                              <span className="font-medium">Fin de prueba:</span>
                              <p>{formatDate(trial.trialEndDate)}</p>
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </DialogContent>
            </Dialog>
          </div>
        </CardHeader>
        <CardContent>
          {trialsLoading ? (
            <div className="space-y-2">
              {[1, 2, 3].map((i) => (
                <div key={i} className="h-16 bg-gray-200 rounded animate-pulse" />
              ))}
            </div>
          ) : trialSignups.length === 0 ? (
            <p className="text-muted-foreground text-center py-8">
              No hay solicitudes de prueba registradas
            </p>
          ) : (
            <div className="space-y-3">
              {trialSignups.slice(0, 5).map((trial) => (
                <div key={trial.id} className="flex items-center justify-between p-3 border rounded-lg" data-testid={`trial-preview-${trial.id}`}>
                  <div>
                    <div className="flex items-center gap-3">
                      <p className="font-medium">{trial.businessName}</p>
                      {getStatusBadge(trial.status)}
                      {!trial.notifiedAdmin && (
                        <AlertTriangle className="h-4 w-4 text-yellow-600" />
                      )}
                    </div>
                    <p className="text-sm text-muted-foreground">
                      {trial.contactEmail} • {formatDate(trial.createdAt)}
                    </p>
                  </div>
                  <div className="text-right text-sm">
                    <p className="text-muted-foreground">Prueba hasta</p>
                    <p className="font-medium">{formatDate(trial.trialEndDate)}</p>
                  </div>
                </div>
              ))}

              {trialSignups.length > 5 && (
                <p className="text-center text-sm text-muted-foreground pt-2">
                  Y {trialSignups.length - 5} solicitudes más...
                </p>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/EnhancedCompetitor.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { 
  TrendingUp, 
  Users, 
  Star,
  BarChart3,
  Search,
  Trophy,
  Target,
  AlertTriangle,
  CheckCircle2,
  Globe,
  Calendar,
  Eye
} from "lucide-react";
import type { Location, CompetitorAnalysisRecord } from "@shared/schema";

const competitorAnalysisSchema = z.object({
  competitorName: z.string().min(1, "Nombre del competidor es requerido"),
  competitorWebsite: z.string().url("URL válida requerida").optional().or(z.literal("")),
  analysisType: z.enum(["reviews", "content", "seo", "full"]).default("full")
});

type CompetitorAnalysisForm = z.infer<typeof competitorAnalysisSchema>;

interface AnalysisData {
  averageRating: number;
  totalReviews: number;
  recentReviews: number;
  responseRate: number;
  contentFrequency: number;
  seoScore: number;
  keywordRankings: Array<{
    keyword: string;
    position: number;
    difficulty: string;
  }>;
  socialPresence: {
    platforms: string[];
    followers: number;
    engagement: number;
  };
}

interface Recommendation {
  category: string;
  priority: "high" | "medium" | "low";
  action: string;
  impact: string;
}

export default function EnhancedCompetitorAnalysis() {
  const { toast } = useToast();
  const [selectedLocation, setSelectedLocation] = useState<string>("");
  const [selectedAnalysis, setSelectedAnalysis] = useState<CompetitorAnalysisRecord | null>(null);

  const form = useForm<CompetitorAnalysisForm>({
    resolver: zodResolver(competitorAnalysisSchema),
    defaultValues: {
      competitorName: "",
      competitorWebsite: "",
      analysisType: "full"
    }
  });

  // Get locations
  const { data: locations = [] } = useQuery<Location[]>({
    queryKey: ['/api/businesses/locations'],
  });

  // Get competitor analyses for selected location
  const { data: analyses = [], isLoading, refetch } = useQuery<CompetitorAnalysisRecord[]>({
    queryKey: ['/api/locations', selectedLocation, 'competitor-analysis'],
    enabled: !!selectedLocation,
  });

  // Create competitor analysis mutation
  const createAnalysis = useMutation({
    mutationFn: async (data: CompetitorAnalysisForm) => {
      const response = await apiRequest(`/api/locations/${selectedLocation}/competitor-analysis`, {
        method: 'POST',
        data
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Análisis Creado",
        description: "El análisis de competencia se completó exitosamente.",
      });
      form.reset();
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo completar el análisis de competencia.",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (data: CompetitorAnalysisForm) => {
    createAnalysis.mutate(data);
  };

  const parseAnalysisData = (jsonData: string): AnalysisData | null => {
    try {
      return JSON.parse(jsonData);
    } catch {
      return null;
    }
  };

  const parseRecommendations = (jsonData: string): Recommendation[] => {
    try {
      return JSON.parse(jsonData);
    } catch {
      return [];
    }
  };

  const getCompetitiveScoreBadge = (score: number) => {
    if (score >= 80) return <Badge className="bg-green-100 text-green-800">Excelente</Badge>;
    if (score >= 60) return <Badge className="bg-yellow-100 text-yellow-800">Bueno</Badge>;
    if (score >= 40) return <Badge className="bg-orange-100 text-orange-800">Regular</Badge>;
    return <Badge className="bg-red-100 text-red-800">Necesita Mejora</Badge>;
  };

  const getMarketPositionIcon = (position: string) => {
    switch (position) {
      case 'leader':
        return <Trophy className="h-4 w-4 text-yellow-600" />;
      case 'challenger':
        return <Target className="h-4 w-4 text-blue-600" />;
      case 'follower':
        return <Users className="h-4 w-4 text-gray-600" />;
      case 'niche':
        return <Star className="h-4 w-4 text-purple-600" />;
      default:
        return <BarChart3 className="h-4 w-4 text-gray-600" />;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high':
        return 'text-red-600 bg-red-50';
      case 'medium':
        return 'text-yellow-600 bg-yellow-50';
      case 'low':
        return 'text-green-600 bg-green-50';
      default:
        return 'text-gray-600 bg-gray-50';
    }
  };

  const formatDate = (dateInput: string | Date) => {
    const date = dateInput instanceof Date ? dateInput : new Date(dateInput);
    return date.toLocaleDateString('es-MX', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  return (
    <div className="space-y-6" data-testid="competitor-analysis">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight" data-testid="title-competitor-analysis">Análisis de Competencia</h1>
          <p className="text-muted-foreground">
            Analiza a tu competencia y descubre oportunidades de mejora
          </p>
        </div>
      </div>

      {/* Location Selector */}
      <Card data-testid="location-selector">
        <CardHeader>
          <CardTitle>Seleccionar Ubicación</CardTitle>
        </CardHeader>
        <CardContent>
          <Select value={selectedLocation} onValueChange={setSelectedLocation}>
            <SelectTrigger data-testid="select-location">
              <SelectValue placeholder="Selecciona una ubicación" />
            </SelectTrigger>
            <SelectContent>
              {locations.map((location) => (
                <SelectItem key={location.id} value={location.id}>
                  {location.name} - {location.city}, {location.state}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {selectedLocation && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Analysis Form */}
          <Card data-testid="analysis-form">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Search className="h-5 w-5" />
                Nuevo Análisis
              </CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="competitorName">Nombre del Competidor *</Label>
                  <Input
                    id="competitorName"
                    {...form.register("competitorName")}
                    placeholder="Ej: Restaurante Central"
                    data-testid="input-competitor-name"
                  />
                  {form.formState.errors.competitorName && (
                    <p className="text-sm text-red-600">{form.formState.errors.competitorName.message}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="competitorWebsite">Sitio Web (Opcional)</Label>
                  <Input
                    id="competitorWebsite"
                    type="url"
                    {...form.register("competitorWebsite")}
                    placeholder="https://competidor.com"
                    data-testid="input-competitor-website"
                  />
                  {form.formState.errors.competitorWebsite && (
                    <p className="text-sm text-red-600">{form.formState.errors.competitorWebsite.message}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="analysisType">Tipo de Análisis</Label>
                  <Select 
                    value={form.watch("analysisType")} 
                    onValueChange={(value) => form.setValue("analysisType", value as any)}
                  >
                    <SelectTrigger data-testid="select-analysis-type">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="full">Análisis Completo</SelectItem>
                      <SelectItem value="reviews">Solo Reseñas</SelectItem>
                      <SelectItem value="content">Solo Contenido</SelectItem>
                      <SelectItem value="seo">Solo SEO</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <Button 
                  type="submit" 
                  className="w-full"
                  disabled={createAnalysis.isPending}
                  data-testid="button-create-analysis"
                >
                  {createAnalysis.isPending ? 'Analizando...' : 'Analizar Competidor'}
                </Button>
              </form>
            </CardContent>
          </Card>

          {/* Analyses List */}
          <Card className="lg:col-span-2" data-testid="analyses-list">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <BarChart3 className="h-5 w-5" />
                Análisis Realizados
              </CardTitle>
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <div className="space-y-4">
                  {[1, 2, 3].map((i) => (
                    <div key={i} className="h-24 bg-gray-200 rounded animate-pulse" />
                  ))}
                </div>
              ) : analyses.length === 0 ? (
                <div className="text-center py-8 space-y-2">
                  <Search className="h-12 w-12 text-muted-foreground mx-auto" />
                  <h3 className="text-lg font-semibold">No hay análisis realizados</h3>
                  <p className="text-muted-foreground">
                    Crea tu primer análisis de competencia
                  </p>
                </div>
              ) : (
                <div className="space-y-4">
                  {analyses.map((analysis) => {
                    const analysisData = parseAnalysisData(analysis.analysisData);

                    return (
                      <div 
                        key={analysis.id} 
                        className={`border rounded-lg p-4 cursor-pointer transition-colors ${
                          selectedAnalysis?.id === analysis.id ? 'bg-muted' : 'hover:bg-muted/50'
                        }`}
                        onClick={() => setSelectedAnalysis(analysis)}
                        data-testid={`analysis-${analysis.id}`}
                      >
                        <div className="flex items-start justify-between mb-3">
                          <div>
                            <h4 className="font-semibold flex items-center gap-2" data-testid={`competitor-name-${analysis.id}`}>
                              {analysis.competitorName}
                              {getMarketPositionIcon(analysis.marketPosition || 'follower')}
                            </h4>
                            <p className="text-sm text-muted-foreground capitalize">
                              Análisis {analysis.analysisType} • {formatDate(analysis.analysisDate)}
                            </p>
                          </div>
                          <div className="flex items-center gap-2">
                            {analysis.competitiveScore && getCompetitiveScoreBadge(analysis.competitiveScore)}
                            <Badge variant="outline" className="capitalize">
                              {analysis.marketPosition || 'Follower'}
                            </Badge>
                          </div>
                        </div>

                        {analysisData && (
                          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                            <div className="text-center">
                              <p className="text-muted-foreground">Rating</p>
                              <p className="font-semibold">{analysisData.averageRating.toFixed(1)}⭐</p>
                            </div>
                            <div className="text-center">
                              <p className="text-muted-foreground">Reseñas</p>
                              <p className="font-semibold">{analysisData.totalReviews}</p>
                            </div>
                            <div className="text-center">
                              <p className="text-muted-foreground">Respuesta</p>
                              <p className="font-semibold">{analysisData.responseRate}%</p>
                            </div>
                            <div className="text-center">
                              <p className="text-muted-foreground">SEO Score</p>
                              <p className="font-semibold">{analysisData.seoScore}/100</p>
                            </div>
                          </div>
                        )}

                        {analysis.competitorWebsite && (
                          <div className="mt-3 pt-3 border-t">
                            <a 
                              href={analysis.competitorWebsite} 
                              target="_blank" 
                              className="text-sm text-primary hover:underline flex items-center gap-1"
                              onClick={(e) => e.stopPropagation()}
                            >
                              <Globe className="h-3 w-3" />
                              Visitar sitio web
                            </a>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      )}

      {/* Detailed Analysis View */}
      {selectedAnalysis && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Analysis Details */}
          <Card data-testid="analysis-details">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Eye className="h-5 w-5" />
                Detalles del Análisis
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {(() => {
                const analysisData = parseAnalysisData(selectedAnalysis.analysisData);
                const strengthsWeaknesses = selectedAnalysis.strengthsWeaknesses ? 
                  JSON.parse(selectedAnalysis.strengthsWeaknesses) : null;

                return (
                  <>
                    {analysisData && (
                      <>
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-2">
                            <h4 className="font-semibold">Métricas de Reseñas</h4>
                            <div className="space-y-1 text-sm">
                              <p>Rating promedio: <span className="font-medium">{analysisData.averageRating.toFixed(1)}⭐</span></p>
                              <p>Total de reseñas: <span className="font-medium">{analysisData.totalReviews}</span></p>
                              <p>Reseñas recientes: <span className="font-medium">{analysisData.recentReviews}</span></p>
                              <p>Tasa de respuesta: <span className="font-medium">{analysisData.responseRate}%</span></p>
                            </div>
                          </div>

                          <div className="space-y-2">
                            <h4 className="font-semibold">Presencia Digital</h4>
                            <div className="space-y-1 text-sm">
                              <p>Score SEO: <span className="font-medium">{analysisData.seoScore}/100</span></p>
                              <p>Frecuencia de contenido: <span className="font-medium">{analysisData.contentFrequency}/semana</span></p>
                              <p>Seguidores: <span className="font-medium">{analysisData.socialPresence.followers.toLocaleString()}</span></p>
                              <p>Engagement: <span className="font-medium">{analysisData.socialPresence.engagement}%</span></p>
                            </div>
                          </div>
                        </div>

                        {analysisData.keywordRankings && analysisData.keywordRankings.length > 0 && (
                          <div className="space-y-2">
                            <h4 className="font-semibold">Ranking de Keywords</h4>
                            <div className="space-y-2">
                              {analysisData.keywordRankings.slice(0, 5).map((keyword, index) => (
                                <div key={index} className="flex items-center justify-between text-sm border rounded p-2">
                                  <span>{keyword.keyword}</span>
                                  <div className="flex items-center gap-2">
                                    <Badge variant="outline">#{keyword.position}</Badge>
                                    <Badge 
                                      variant={keyword.difficulty === 'high' ? 'destructive' : 
                                              keyword.difficulty === 'medium' ? 'secondary' : 'default'}
                                    >
                                      {keyword.difficulty}
                                    </Badge>
                                  </div>
                                </div>
                              ))}
                            </div>
                          </div>
                        )}

                        {strengthsWeaknesses && (
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {strengthsWeaknesses.strengths && (
                              <div className="space-y-2">
                                <h4 className="font-semibold text-green-600 flex items-center gap-1">
                                  <CheckCircle2 className="h-4 w-4" />
                                  Fortalezas
                                </h4>
                                <ul className="space-y-1 text-sm">
                                  {strengthsWeaknesses.strengths.map((strength: string, index: number) => (
                                    <li key={index} className="flex items-start gap-2">
                                      <CheckCircle2 className="h-3 w-3 text-green-600 mt-0.5 flex-shrink-0" />
                                      {strength}
                                    </li>
                                  ))}
                                </ul>
                              </div>
                            )}

                            {strengthsWeaknesses.weaknesses && (
                              <div className="space-y-2">
                                <h4 className="font-semibold text-yellow-600 flex items-center gap-1">
                                  <AlertTriangle className="h-4 w-4" />
                                  Debilidades
                                </h4>
                                <ul className="space-y-1 text-sm">
                                  {strengthsWeaknesses.weaknesses.map((weakness: string, index: number) => (
                                    <li key={index} className="flex items-start gap-2">
                                      <AlertTriangle className="h-3 w-3 text-yellow-600 mt-0.5 flex-shrink-0" />
                                      {weakness}
                                    </li>
                                  ))}
                                </ul>
                              </div>
                            )}
                          </div>
                        )}
                      </>
                    )}
                  </>
                );
              })()}
            </CardContent>
          </Card>

          {/* Recommendations */}
          <Card data-testid="recommendations">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Target className="h-5 w-5" />
                Recomendaciones
              </CardTitle>
            </CardHeader>
            <CardContent>
              {(() => {
                const recommendations = selectedAnalysis.recommendations ? 
                  parseRecommendations(selectedAnalysis.recommendations) : [];

                return recommendations.length === 0 ? (
                  <p className="text-muted-foreground text-center py-8">
                    No hay recomendaciones disponibles para este análisis
                  </p>
                ) : (
                  <div className="space-y-3">
                    {recommendations.map((rec, index) => (
                      <div key={index} className="border rounded-lg p-3 space-y-2">
                        <div className="flex items-center justify-between">
                          <h4 className="font-semibold text-sm">{rec.category}</h4>
                          <Badge className={getPriorityColor(rec.priority)}>
                            {rec.priority === 'high' ? 'Alta' : 
                             rec.priority === 'medium' ? 'Media' : 'Baja'} Prioridad
                          </Badge>
                        </div>
                        <p className="text-sm text-muted-foreground">{rec.action}</p>
                        <p className="text-xs text-green-600 font-medium">
                          Impacto esperado: {rec.impact}
                        </p>
                      </div>
                    ))}
                  </div>
                );
              })()}
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

client/src/components/ReportExporter.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { 
  Download, 
  FileText, 
  TableIcon,
  Calendar,
  Clock,
  CheckCircle2,
  AlertCircle,
  Loader2,
  Trash2,
  Eye
} from "lucide-react";
import type { Location, ReportExport } from "@shared/schema";
import { DatePickerWithRange } from "@/components/ui/date-picker";
import { DateRange } from "react-day-picker";

const exportReportSchema = z.object({
  reportType: z.enum(["reputation", "content_performance", "competitor_analysis"]),
  locationIds: z.array(z.string()).min(1, "Selecciona al menos una ubicación"),
  format: z.enum(["pdf", "excel"]).default("pdf"),
  dateRange: z.object({
    startDate: z.string().date(),
    endDate: z.string().date()
  }),
  filters: z.record(z.any()).optional()
});

type ReportExportForm = z.infer<typeof exportReportSchema>;

export default function ReportExporter() {
  const { toast } = useToast();
  const [selectedLocations, setSelectedLocations] = useState<string[]>([]);
  const [dateRange, setDateRange] = useState<DateRange | undefined>();

  const form = useForm<ReportExportForm>({
    resolver: zodResolver(exportReportSchema),
    defaultValues: {
      reportType: "reputation",
      locationIds: [],
      format: "pdf",
      dateRange: {
        startDate: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0]
      },
      filters: {}
    }
  });

  // Get locations
  const { data: locations = [] } = useQuery<Location[]>({
    queryKey: ['/api/businesses/locations'],
  });

  // Get export history
  const { data: exports = [], isLoading: exportsLoading, refetch } = useQuery<ReportExport[]>({
    queryKey: ['/api/reports/exports'],
  });

  // Export report mutation
  const exportReport = useMutation({
    mutationFn: async (data: ReportExportForm) => {
      const response = await apiRequest('/api/reports/export', {
        method: 'POST',
        data
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Reporte en Proceso",
        description: "Tu reporte está siendo generado. Te notificaremos cuando esté listo.",
      });
      form.reset();
      setSelectedLocations([]);
      setDateRange(undefined);
      refetch();
    },
    onError: () => {
      toast({
        title: "Error",
        description: "No se pudo generar el reporte. Intenta de nuevo.",
        variant: "destructive",
      });
    },
  });

  // Download report mutation
  const downloadReport = useMutation({
    mutationFn: async (exportId: string) => {
      const response = await fetch(`/api/reports/download/${exportId}`, {
        method: 'GET'
      });

      if (!response.ok) {
        throw new Error('Failed to download report');
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `reporte_${exportId}.pdf`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);

      return blob;
    },
    onSuccess: () => {
      toast({
        title: "Descarga Completada",
        description: "El reporte se descargó correctamente.",
      });
    },
    onError: () => {
      toast({
        title: "Error de Descarga",
        description: "No se pudo descargar el reporte.",
        variant: "destructive",
      });
    },
  });

  const handleLocationChange = (locationId: string, checked: boolean) => {
    if (checked) {
      setSelectedLocations(prev => [...prev, locationId]);
    } else {
      setSelectedLocations(prev => prev.filter(id => id !== locationId));
    }
  };

  const handleSubmit = (data: ReportExportForm) => {
    const exportData = {
      ...data,
      locationIds: selectedLocations,
      dateRange: {
        startDate: dateRange?.from?.toISOString().split('T')[0] || data.dateRange.startDate,
        endDate: dateRange?.to?.toISOString().split('T')[0] || data.dateRange.endDate
      }
    };

    exportReport.mutate(exportData);
  };

  const getStatusBadge = (status: string) => {
    const statusMap = {
      processing: { label: 'Procesando', variant: 'secondary' as const, icon: Loader2 },
      completed: { label: 'Completado', variant: 'default' as const, icon: CheckCircle2 },
      failed: { label: 'Error', variant: 'destructive' as const, icon: AlertCircle },
    };

    const statusInfo = statusMap[status as keyof typeof statusMap] || { 
      label: status, 
      variant: 'outline' as const, 
      icon: Clock 
    };

    return (
      <Badge variant={statusInfo.variant} className="flex items-center gap-1">
        <statusInfo.icon className="h-3 w-3" />
        {statusInfo.label}
      </Badge>
    );
  };

  const getReportTypeLabel = (type: string) => {
    const typeMap = {
      reputation: 'Análisis de Reputación',
      content_performance: 'Rendimiento de Contenido',
      competitor_analysis: 'Análisis de Competencia'
    };
    return typeMap[type as keyof typeof typeMap] || type;
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatDate = (date: Date | string) => {
    const dateObj = typeof date === 'string' ? new Date(date) : date;
    return dateObj.toLocaleDateString('es-MX', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-6" data-testid="report-exporter">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight" data-testid="title-reports">Exportar Reportes</h1>
          <p className="text-muted-foreground">
            Genera reportes detallados en PDF o Excel con métricas de tu negocio
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Export Form */}
        <Card data-testid="export-form">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5" />
              Generar Nuevo Reporte
            </CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
              <div className="space-y-2">
                <Label>Tipo de Reporte</Label>
                <Select 
                  value={form.watch("reportType")} 
                  onValueChange={(value) => form.setValue("reportType", value as any)}
                >
                  <SelectTrigger data-testid="select-report-type">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="reputation">Análisis de Reputación</SelectItem>
                    <SelectItem value="content_performance">Rendimiento de Contenido</SelectItem>
                    <SelectItem value="competitor_analysis">Análisis de Competencia</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Ubicaciones</Label>
                <div className="grid grid-cols-1 gap-3 max-h-48 overflow-y-auto border rounded-md p-3">
                  {locations.map((location) => (
                    <div key={location.id} className="flex items-center space-x-2">
                      <Checkbox
                        id={location.id}
                        checked={selectedLocations.includes(location.id)}
                        onCheckedChange={(checked) => handleLocationChange(location.id, !!checked)}
                        data-testid={`checkbox-location-${location.id}`}
                      />
                      <Label htmlFor={location.id} className="text-sm flex-1">
                        {location.name} - {location.city}, {location.state}
                      </Label>
                    </div>
                  ))}
                </div>
                {selectedLocations.length === 0 && (
                  <p className="text-sm text-red-600">Selecciona al menos una ubicación</p>
                )}
              </div>

              <div className="space-y-2">
                <Label>Formato de Reporte</Label>
                <Select 
                  value={form.watch("format")} 
                  onValueChange={(value) => form.setValue("format", value as any)}
                >
                  <SelectTrigger data-testid="select-format">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="pdf">
                      <div className="flex items-center gap-2">
                        <FileText className="h-4 w-4" />
                        PDF
                      </div>
                    </SelectItem>
                    <SelectItem value="excel">
                      <div className="flex items-center gap-2">
                        <TableIcon className="h-4 w-4" />
                        Excel
                      </div>
                    </SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Rango de Fechas</Label>
                <DatePickerWithRange
                  date={dateRange}
                  onDateChange={setDateRange}
                  placeholder="Selecciona un rango de fechas"
                  data-testid="date-picker-range"
                />
              </div>

              <Button 
                type="submit" 
                className="w-full"
                disabled={exportReport.isPending || selectedLocations.length === 0}
                data-testid="button-generate-report"
              >
                {exportReport.isPending ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Generando Reporte...
                  </>
                ) : (
                  <>
                    <Download className="h-4 w-4 mr-2" />
                    Generar Reporte
                  </>
                )}
              </Button>
            </form>
          </CardContent>
        </Card>

        {/* Export History */}
        <Card data-testid="export-history">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Clock className="h-5 w-5" />
              Historial de Reportes
            </CardTitle>
          </CardHeader>
          <CardContent>
            {exportsLoading ? (
              <div className="space-y-4">
                {[1, 2, 3].map((i) => (
                  <div key={i} className="h-20 bg-gray-200 rounded animate-pulse" />
                ))}
              </div>
            ) : exports.length === 0 ? (
              <div className="text-center py-8 space-y-2">
                <FileText className="h-12 w-12 text-muted-foreground mx-auto" />
                <h3 className="text-lg font-semibold">No hay reportes generados</h3>
                <p className="text-muted-foreground">
                  Genera tu primer reporte para ver el historial
                </p>
              </div>
            ) : (
              <div className="space-y-4 max-h-96 overflow-y-auto">
                {exports.map((exportItem) => (
                  <div key={exportItem.id} className="border rounded-lg p-4 space-y-3" data-testid={`export-${exportItem.id}`}>
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                          {getStatusBadge(exportItem.status)}
                          <Badge variant="outline" className="capitalize">
                            {exportItem.format.toUpperCase()}
                          </Badge>
                        </div>
                        <h4 className="font-semibold" data-testid={`export-type-${exportItem.id}`}>
                          {getReportTypeLabel(exportItem.reportType)}
                        </h4>
                        <p className="text-sm text-muted-foreground">
                          {(() => {
                            const dateRange = JSON.parse(exportItem.dateRange);
                            return `${new Date(dateRange.startDate).toLocaleDateString('es-MX')} - ${new Date(dateRange.endDate).toLocaleDateString('es-MX')}`;
                          })()}
                        </p>
                      </div>
                      <div className="flex items-center gap-1">
                        {exportItem.status === 'completed' && exportItem.fileUrl && (
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => downloadReport.mutate(exportItem.id)}
                            disabled={downloadReport.isPending}
                            data-testid={`button-download-${exportItem.id}`}
                          >
                            <Download className="h-4 w-4" />
                          </Button>
                        )}
                        <Button
                          size="sm"
                          variant="outline"
                          data-testid={`button-view-${exportItem.id}`}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>

                    <div className="flex items-center justify-between text-xs text-muted-foreground">
                      <div className="flex items-center gap-1">
                        <Calendar className="h-3 w-3" />
                        <span>Generado: {formatDate(exportItem.createdAt)}</span>
                      </div>
                      {exportItem.fileSize && (
                        <span>{formatFileSize(exportItem.fileSize)}</span>
                      )}
                    </div>

                    {exportItem.status === 'failed' && exportItem.errorMessage && (
                      <div className="p-2 bg-red-50 border border-red-200 rounded text-sm text-red-800">
                        <div className="flex items-center gap-1">
                          <AlertCircle className="h-3 w-3" />
                          <span>Error: {exportItem.errorMessage}</span>
                        </div>
                      </div>
                    )}

                    {exportItem.expiresAt && new Date(exportItem.expiresAt) > new Date() && (
                      <div className="text-xs text-muted-foreground">
                        Disponible hasta: {formatDate(exportItem.expiresAt)}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

